class TrieNode:
    """Represent a single node in a trie."""

    def __init__(self) -> None:
        """Initialize an empty node with no children."""
        self.children: dict[str, "TrieNode"] = {}
        self.is_end_of_word: bool = False


class Trie:
    """A prefix tree for storing and retrieving words."""

    def __init__(self) -> None:
        """Initialize an empty trie."""
        self.root: TrieNode = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie."""
        node = self.root

        for character in word:
            if character not in node.children:
                node.children[character] = TrieNode()
            node = node.children[character]

        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        """Return whether an exact, complete word exists in the trie."""
        node = self._find_node(word)
        return node is not None and node.is_end_of_word

    def starts_with(self, prefix: str) -> bool:
        """Return whether the trie contains the given prefix."""
        return self._find_node(prefix) is not None

    def autocomplete(self, prefix: str, max_results: int = 5) -> list[str]:
        """Return alphabetically sorted words beginning with the prefix."""
        if max_results <= 0:
            return []

        prefix_node = self._find_node(prefix)
        if prefix_node is None:
            return []

        results: list[str] = []

        def dfs(node: TrieNode, current_word: str) -> None:
            """Collect completions below a node using depth-first search."""
            if len(results) >= max_results:
                return

            if node.is_end_of_word:
                results.append(current_word)

            for character in sorted(node.children):
                if len(results) >= max_results:
                    break
                dfs(node.children[character], current_word + character)

        dfs(prefix_node, prefix)
        return results

    def _find_node(self, text: str) -> TrieNode | None:
        """Return the node reached by text, or None if it is absent."""
        node = self.root

        for character in text:
            if character not in node.children:
                return None
            node = node.children[character]

        return node


if __name__ == "__main__":
    trie = Trie()

    words = ["apple", "app", "application", "apt", "bat", "batch", "bath"]
    for word in words:
        trie.insert(word)

    print('search("app") =>', trie.search("app"))
    print('search("ap") =>', trie.search("ap"))
    print('starts_with("ap") =>', trie.starts_with("ap"))
    print('autocomplete("app") =>', trie.autocomplete("app"))
    print('autocomplete("bat") =>', trie.autocomplete("bat"))
    print('autocomplete("xyz") =>', trie.autocomplete("xyz"))
